1	/**
2	 * Orchestrator side-effect dispatcher.
3	 *
4	 * Translates an ExecutorResult into the correct set of side effects:
5	 *   in_review  → mutate task YAML to in_review, append log
6	 *                (pr_url recorded from result.pr_url if present — executor opened it)
7	 *   blocked    → mutate task YAML to blocked, append log
8	 *                (pr_url recorded from result.pr_url if present — draft PR documents failure)
9	 *   failed     → mutate task YAML to blocked (executor_failed:*), append log
10	 *
11	 * Revised D5: the executor owns impl-PR creation (via /pr-create skill).
12	 * The orchestrator no longer opens impl PRs — it only records the pr_url
13	 * reported by the executor in result.json.
14	 *
15	 * Extracted from main.ts so seam tests can inject any ExecutorAdapter and
16	 * verify the resulting task state without running the full bootstrap + poll loop.
17	 */
18	
19	import type { ExecutorResult } from "@workflow/runtime-abi";
20	import type { TaskLogEntry } from "../types/task.js";
21	import type { NotificationPort } from "../notifications/notification.port.js";
22	import type { TaskContext } from "../notifications/notification.types.js";
23	import { mutateTaskYaml } from "./mutate-task-yaml.js";
24	import { mutateTaskYamlDirect } from "./mutate-task-yaml-direct.js";
25	import { appendLogEntry } from "./append-log.js";
26	import { taskBranchName } from "../paths.js";
27	import { tryReadTaskFromBranch } from "../task-branch-state.js";
28	import { curlJson } from "../utils/curl-json.js";
29	
30	const EXECUTOR_MAX_RETRIES = Number(process.env.EXECUTOR_MAX_RETRIES ?? "3");
31	
32	export interface DispatchExecutorResultOpts {
33	  result: ExecutorResult;
34	  workspaceRoot: string;
35	  featureId: string;
36	  taskId: string;
37	  taskBranch: string;
38	  taskTitle: string;
39	  taskRepoUrl: string;
40	  taskBaseBranch: string;
41	  githubToken: string;
42	  gitAuthorEmail: string;
43	  gitAuthorName?: string;
44	  sshKeyPath?: string;
45	  notifier?: NotificationPort | null;
46	  emit: (event: Record<string, unknown>) => void;
47	}
48	
49	/**
50	 * Apply the side effects that correspond to an executor result.
51	 * Called by the orchestrator polling loop after adapter.run() returns.
52	 * Partially throwing: mutateTaskYaml failures are thrown so the reap loop
53	 * can nack the completion and retry. appendLogEntry failures are emitted but
54	 * swallowed — a missing log entry is non-fatal.
55	 */
56	export async function dispatchExecutorResult(
57	  opts: DispatchExecutorResultOpts,
58	): Promise<void> {
59	  const {
60	    result,
61	    workspaceRoot,
62	    featureId,
63	    taskId,
64	    taskBranch,
65	    taskTitle,
66	    taskRepoUrl,
67	    gitAuthorEmail,
68	    gitAuthorName,
69	    sshKeyPath,
70	    githubToken,
71	    notifier,
72	    emit,
73	  } = opts;
74	
75	  // ── Max-turns retry ───────────────────────────────────────────────────────
76	  if (
77	    result.terminal_status === "blocked" &&
78	    typeof result.blocked_reason === "string" &&
79	    result.blocked_reason.startsWith("max_turns")
80	  ) {
81	    const branch = taskBranchName(featureId, taskId);
82	    const relPath = `docs/features/${featureId}/tasks/${taskId}.yaml`;
83	    const branchTask = tryReadTaskFromBranch(workspaceRoot, branch, relPath);
84	    if (branchTask) {
85	      const retriedCount = (branchTask.log ?? []).filter((e) => e.action === "retried").length;
86	      if (retriedCount < EXECUTOR_MAX_RETRIES) {
87	        const mutateErr = mutateTaskYamlDirect({
88	          workspaceRoot, featureId, taskId, taskBranch, status: "ready",
89	          logEntry: {
90	            action: "retried", by: gitAuthorEmail,
91	            note: `Max-turns block reset to ready (attempt ${retriedCount + 1} of ${EXECUTOR_MAX_RETRIES}).`,
92	          },
93	          gitAuthorEmail, gitAuthorName, sshKeyPath,
94	          commitMessage: `chore(${taskId}): retried — max-turns reset (${retriedCount + 1}/${EXECUTOR_MAX_RETRIES})`,
95	        });
96	        if (mutateErr) {
97	          emit({ type: "retry_mutate_failed", task_id: taskId, feature_id: featureId, details: mutateErr });
98	        } else {
99	          emit({ type: "task_retried", task_id: taskId, feature_id: featureId, attempt: retriedCount + 1, max: EXECUTOR_MAX_RETRIES });
100	          return;
101	        }
102	      } else {
103	        emit({ type: "task_max_retries_exceeded", task_id: taskId, feature_id: featureId, max: EXECUTOR_MAX_RETRIES });
104	      }
105	    }
106	  }
107	
108	  // pr_url from result.json — set by executor when it opened a PR.
109	  // Present on any terminal_status when commits were pushed and a PR was opened.
110	  const prUrl = result.pr_url;
111	
112	  if (result.terminal_status === "in_review") {
113	    if (prUrl) {
114	      emit({ type: "impl_pr_recorded", task_id: taskId, feature_id: featureId, pr_url: prUrl });
115	      const prMatch = /github\.com\/([^/]+)\/([^/]+)\/pull\/(\d+)/.exec(prUrl);
116	      if (prMatch && githubToken) {
117	        const [, owner, repo, prNumber] = prMatch;
118	        // wipTitle is set only after a successful promote, so the title PATCH
119	        // only runs when the draft→ready transition actually completed.
120	        let wipTitle: string | undefined;
121	        try {
122	          // REST PATCH draft:false is silently ignored by GitHub — use GraphQL instead.
123	          const prData = curlJson([
124	            "-s", "--fail",
125	            "-H", `Authorization: token ${githubToken}`,
126	            "-H", "Accept: application/vnd.github+json",
127	            `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}`,
128	          ]) as { node_id?: string; title?: string };
129	          const nodeId = prData.node_id;
130	          if (!nodeId) throw new Error("PR node_id missing from REST response");
131	          curlJson([
132	            "-s", "--fail", "-X", "POST",
133	            "-H", `Authorization: token ${githubToken}`,
134	            "-H", "Content-Type: application/json",
135	            "-d", JSON.stringify({
136	              query: `mutation { markPullRequestReadyForReview(input: { pullRequestId: "${nodeId}" }) { pullRequest { isDraft } } }`,
137	            }),
138	            "https://api.github.com/graphql",
139	          ]);
140	          // Capture the WIP title after promote succeeds so cleanup runs in its own try/catch.
141	          if (prData.title?.startsWith("[WIP]")) wipTitle = prData.title;
142	        } catch (e) {
143	          emit({ type: "task_pr_promote_failed", task_id: taskId, feature_id: featureId, details: String(e) });
144	        }
145	        // Clean up WIP title/body set by the recovery routine when agent crashed.
146	        // Runs independently of promote so a PATCH failure doesn't misattribute as promote failure.
147	        if (wipTitle !== undefined) {
148	          try {
149	            // Preserve the conventional-commit type embedded in the WIP title (feat/fix/chore/…).
150	            const prType = /^\[WIP\] (\w+)\(/.exec(wipTitle)?.[1] ?? "feat";
151	            const cleanTitle = `${prType}(${featureId}/${taskId}): ${taskTitle}`;
152	            const cleanBody = [
153	              `## ${taskTitle}`,
154	              "",
155	              `**Feature:** ${featureId}`,
156	              `**Task:** ${taskId}`,
157	              `**Branch:** \`${taskBranch}\``,
158	            ].join("\n");
159	            curlJson([
160	              "-s", "--fail", "-X", "PATCH",
161	              "-H", `Authorization: token ${githubToken}`,
162	              "-H", "Accept: application/vnd.github+json",
163	              "-H", "Content-Type: application/json",
164	              "-d", JSON.stringify({ title: cleanTitle, body: cleanBody }),
165	              `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}`,
166	            ]);
167	            emit({ type: "task_pr_title_updated", task_id: taskId, feature_id: featureId, pr_url: prUrl });
168	          } catch (e) {
169	            emit({ type: "task_pr_title_update_failed", task_id: taskId, feature_id: featureId, details: String(e) });
170	          }
171	        }
172	      }
173	    }
174	
175	    const mutateErr = mutateTaskYaml({
176	      workspaceRoot,
177	      featureId,
178	      taskId,
179	      taskBranch,
180	      result,
181	      prUrl,
182	      gitAuthorEmail,
183	      gitAuthorName,
184	      sshKeyPath,
185	    });
186	    if (mutateErr) {
187	      emit({ type: "mutate_task_yaml_failed", task_id: taskId, details: mutateErr });
188	      throw new Error(mutateErr);
189	    }
190	
191	    const runCompletedEntry: Omit<TaskLogEntry, "at"> = {
192	      action: "run_completed",
193	      by: gitAuthorEmail,
194	      note: prUrl ? `Implementation PR: ${prUrl}` : "Implementation complete.",
195	      ...(result.token_usage !== undefined && { token_usage: result.token_usage }),
196	      ...(result.cost_usd !== undefined && { cost_usd: result.cost_usd }),
197	    };
198	
199	    const logErr = appendLogEntry({
200	      workspaceRoot,
201	      featureId,
202	      taskId,
203	      taskBranch,
204	      entry: runCompletedEntry,
205	      gitAuthorEmail,
206	      gitAuthorName,
207	      sshKeyPath,
208	    });
209	    if (logErr) emit({ type: "append_log_failed", task_id: taskId, details: logErr });
210	
211	    if (notifier) {
212	      const ctx: TaskContext = {
213	        title: taskTitle,
214	        status: "in_review",
215	        repo: taskRepoUrl,
216	        branch: taskBranch,
217	        lastUpdatedBy: gitAuthorEmail,
218	        pr: prUrl ? { url: prUrl, status: "open" } : null,
219	      };
220	      try {
221	        await notifier.postTaskMessage(featureId, taskId, "task_status_changed", ctx);
222	      } catch (e) {
223	        emit({ type: "task_notification_failed", task_id: taskId, feature_id: featureId, event: "in_review", error: String(e) });
224	      }
225	    }
226	  } else {
227	    if (prUrl) {
228	      emit({ type: "impl_pr_recorded", task_id: taskId, feature_id: featureId, pr_url: prUrl });
229	    }
230	
231	    const mutateErr = mutateTaskYaml({
232	      workspaceRoot,
233	      featureId,
234	      taskId,
235	      taskBranch,
236	      result,
237	      prUrl,
238	      gitAuthorEmail,
239	      gitAuthorName,
240	      sshKeyPath,
241	    });
242	    if (mutateErr) {
243	      emit({ type: "mutate_task_yaml_failed", task_id: taskId, details: mutateErr });
244	      throw new Error(mutateErr);
245	    }
246	
247	    const blockedEntry: Omit<TaskLogEntry, "at"> = {
248	      action: "blocked",
249	      by: gitAuthorEmail,
250	      note: result.blocked_reason ?? "executor returned non-in_review status",
251	      ...(result.token_usage !== undefined && { token_usage: result.token_usage }),
252	      ...(result.cost_usd !== undefined && { cost_usd: result.cost_usd }),
253	    };
254	
255	    const logErr = appendLogEntry({
256	      workspaceRoot,
257	      featureId,
258	      taskId,
259	      taskBranch,
260	      entry: blockedEntry,
261	      gitAuthorEmail,
262	      gitAuthorName,
263	      sshKeyPath,
264	    });
265	    if (logErr) emit({ type: "append_log_failed", task_id: taskId, details: logErr });
266	
267	    if (notifier) {
268	      const ctx: TaskContext = {
269	        title: taskTitle,
270	        status: "blocked",
271	        repo: taskRepoUrl,
272	        branch: taskBranch,
273	        lastUpdatedBy: gitAuthorEmail,
274	        pr: prUrl ? { url: prUrl, status: "open" } : null,
275	        blockedReason: result.blocked_reason ?? null,
276	      };
277	      try {
278	        await notifier.postTaskMessage(featureId, taskId, "task_status_changed", ctx);
279	      } catch (e) {
280	        emit({ type: "task_notification_failed", task_id: taskId, feature_id: featureId, event: "blocked", error: String(e) });
281	      }
282	    }
283	  }
284	}
