1	/**
2	 * Escalation handler — implements the `escalate` branch of dispatchReviewResult.
3	 *
4	 * Responsibilities:
5	 *   1. Post a task-tied escalation notification via NotificationPort (when injected).
6	 *   2. Mutate the task YAML: status → blocked, blocked_reason, blocked_suggestion.
7	 *   3. Emit `task_escalated` (or `escalation_slack_skipped` when notifier is absent).
8	 */
9	
10	import { mutateTaskYamlDirect } from "./mutate-task-yaml-direct.js";
11	import { taskBranchName } from "../paths.js";
12	import type { NotificationPort } from "../notifications/notification.port.js";
13	
14	const BLOCKED_SUGGESTION = "Human review required — reviewer confidence exhausted or hard CI failure";
15	
16	export interface EscalationOpts {
17	  workspaceRoot: string;
18	  featureId: string;
19	  taskId: string;
20	  taskTitle?: string;
21	  /** Implementation PR URL reported by the executor (task.pr.url). */
22	  prUrl?: string;
23	  /** Escalation reason from reviewer notes. */
24	  notes?: string;
25	  /** Reviewer review URL (GitHub review link). */
26	  reviewUrl?: string;
27	  gitAuthorEmail: string;
28	  gitAuthorName?: string;
29	  sshKeyPath?: string;
30	  /** Injected notification port — used instead of direct webhook call. */
31	  notifier?: NotificationPort | null;
32	  emit: (event: Record<string, unknown>) => void;
33	}
34	
35	/**
36	 * Build a Slack Block Kit payload for the escalation message.
37	 * Kept for backward compatibility with postEscalationSlack (used in tests).
38	 */
39	function buildSlackPayload(opts: EscalationOpts): Record<string, unknown> {
40	  const { featureId, taskId, taskTitle, prUrl, notes, reviewUrl } = opts;
41	  const title = taskTitle ? `${taskId} — ${taskTitle}` : taskId;
42	  const prLink = prUrl ? `<${prUrl}|View PR>` : "_not available_";
43	  const reviewLink = reviewUrl ? `<${reviewUrl}|View review>` : "_not available_";
44	  const reason = notes ?? "No reviewer notes provided.";
45	
46	  return {
47	    text: `[Escalation] Task ${title} requires human review`,
48	    blocks: [
49	      {
50	        type: "header",
51	        text: { type: "plain_text", text: `🚨 Task escalated: ${title}` },
52	      },
53	      {
54	        type: "section",
55	        fields: [
56	          { type: "mrkdwn", text: `*Feature:*\n${featureId}` },
57	          { type: "mrkdwn", text: `*Task:*\n${taskId}` },
58	          { type: "mrkdwn", text: `*PR:*\n${prLink}` },
59	          { type: "mrkdwn", text: `*Review:*\n${reviewLink}` },
60	        ],
61	      },
62	      {
63	        type: "section",
64	        text: { type: "mrkdwn", text: `*Escalation reason:*\n${reason}` },
65	      },
66	      {
67	        type: "section",
68	        text: {
69	          type: "mrkdwn",
70	          text: `*Suggested action:*\n${BLOCKED_SUGGESTION}`,
71	        },
72	      },
73	    ],
74	  };
75	}
76	
77	/**
78	 * Post an escalation message to Slack via the legacy incoming webhook.
79	 * Used when a webhook URL is available outside the notifier injection path.
80	 * Returns true if the message was sent, false if webhookUrl is unset.
81	 * Throws on network/HTTP errors so the caller can handle them.
82	 */
83	export async function postEscalationSlack(
84	  opts: EscalationOpts,
85	  webhookUrl: string,
86	): Promise<void> {
87	  const payload = buildSlackPayload(opts);
88	  const resp = await fetch(webhookUrl, {
89	    method: "POST",
90	    headers: { "Content-Type": "application/json" },
91	    body: JSON.stringify(payload),
92	  });
93	  if (!resp.ok) {
94	    throw new Error(`Slack webhook returned ${resp.status}: ${await resp.text()}`);
