/**
 * Unit tests for dispatchReviewResult.
 *
 * `terminal_status: passed` only emits `review_passed` — it does NOT mark the
 * task done. The mark-done write happens later when the in_review PR poll sees
 * `merged: true` on the implementation PR and calls handleMergedPrs (covered in
 * tests/handle-merged-prs.test.ts).
 *
 * Tests:
 *   1. passed — emits review_passed, task YAML stays in_review
 *   2. passed — self_review_skipped emits reviewer_self_review_skipped before review_passed
 *   3. change_requested routing still works
 *   4. escalate routing still works
 *   5. unknown status — review_blocked retry / escalate after max attempts
 */

import { describe, it, expect, vi, afterEach, beforeEach, beforeAll } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import { spawnSync } from "node:child_process";
import type { Task } from "../src/types/task.js";

// ── Mock git operations ───────────────────────────────────────────────────────

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
});

// ── Fixtures ──────────────────────────────────────────────────────────────────

const FEATURE_ID = "test-feature";
const TASK_ID = "T1";
const TASK_BRANCH = `feature/${FEATURE_ID}-${TASK_ID}`;
const GIT_AUTHOR_EMAIL = "bot@test.com";
const GIT_AUTHOR_NAME = "Test Bot";
const PR_URL = "https://github.com/org/repo/pull/42";

function makeTask(id: string, overrides: Partial<Task> = {}): Task {
  return {
    id,
    title: `Task ${id}`,
    repo: "test-repo",
    status: "in_review",
    depends_on: [],
    blocked_reason: null,
    blocked_context: null,
    branch: `feature/${FEATURE_ID}-${id}`,
    execution: {
      actor_type: "agent",
      last_updated_by: null,
      last_updated_at: null,
    },
    pr: { url: PR_URL, status: "open" },
    workspace_pr: null,
    log: [],
    ...overrides,
  };
}

function mockPushSuccess(): ReturnType<typeof spawnSync> {
  return {
    pid: 0, output: [], stdout: "", stderr: "",
    status: 0, signal: null, error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

function mockPushFailure(stderr = "push rejected"): ReturnType<typeof spawnSync> {
  return {
    pid: 0, output: [], stdout: "", stderr,
    status: 1, signal: null, error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

// ── Temp workspace helpers ────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeWorkspaceWithTasks(tasks: Task[]): string {
  const dir = mkdtempSync(join(tmpdir(), "dispatch-review-result-"));
  tmpDirs.push(dir);
  const tasksDir = join(dir, "docs", "features", FEATURE_ID, "tasks");
  mkdirSync(tasksDir, { recursive: true });
  for (const task of tasks) {
    writeFileSync(join(tasksDir, `${task.id}.yaml`), yamlStringify(task), "utf-8");
  }
  return dir;
}

function readTaskFromDir(wsRoot: string, taskId: string): Task {
  return parseYaml(
    readFileSync(
      join(wsRoot, "docs", "features", FEATURE_ID, "tasks", `${taskId}.yaml`),
      "utf-8",
    ),
  ) as Task;
}

// ── Setup ─────────────────────────────────────────────────────────────────────

let _originalSlackUrl: string | undefined;

beforeAll(() => {
  _originalSlackUrl = process.env["SLACK_WEBHOOK_URL"];
});

beforeEach(() => {
  delete process.env["SLACK_WEBHOOK_URL"];
});

afterEach(() => {
  if (_originalSlackUrl !== undefined) {
    process.env["SLACK_WEBHOOK_URL"] = _originalSlackUrl;
  } else {
    delete process.env["SLACK_WEBHOOK_URL"];
  }
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
  vi.clearAllMocks();
  vi.resetModules();
});

const baseDispatchOpts = {
  workspaceRoot: "/fake",
  featureId: FEATURE_ID,
  taskId: TASK_ID,
  gitAuthorEmail: GIT_AUTHOR_EMAIL,
};

// ── dispatchReviewResult — passed branch ──────────────────────────────────────
//
// `terminal_status: passed` no longer marks the task done. It only emits
// `review_passed`. The mark-done write happens later when the in_review PR poll
// detects `merged: true` on the implementation PR and calls handleMergedPrs —
// see tests/handle-merged-prs.test.ts for the cascade and done-write coverage.

describe("dispatchReviewResult — passed: emits review_passed without marking done", () => {
  it("emits review_passed; task YAML stays in_review and no task_auto_done event", async () => {
    const task = makeTask(TASK_ID, { status: "in_review" });
    const wsRoot = makeWorkspaceWithTasks([task]);

    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "passed", verdict: "approve", confidence: 0.95, notes: "LGTM", review_url: PR_URL },
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      gitAuthorName: GIT_AUTHOR_NAME,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "review_passed")).toBe(true);
    expect(events.some((e) => e.type === "task_auto_done")).toBe(false);
    expect(events.some((e) => e.type === "auto_done_failed")).toBe(false);
    expect(events.some((e) => e.type === "auto_ready_cascade")).toBe(false);

    const updated = readTaskFromDir(wsRoot, TASK_ID);
    expect(updated.status).toBe("in_review");
    expect(updated.log.find((e) => e.action === "done")).toBeUndefined();
  });

  it("emits reviewer_self_review_skipped before review_passed when result.self_review_skipped is true", async () => {
    const task = makeTask(TASK_ID, { status: "in_review" });
    const wsRoot = makeWorkspaceWithTasks([task]);

    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "passed", verdict: "approve", confidence: 0.9, notes: "", review_url: PR_URL, self_review_skipped: true },
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      prUrl: PR_URL,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: (e) => events.push(e),
    });

    const skipIdx = events.findIndex((e) => e.type === "reviewer_self_review_skipped");
    const passedIdx = events.findIndex((e) => e.type === "review_passed");
    expect(skipIdx).toBeGreaterThanOrEqual(0);
    expect(passedIdx).toBeGreaterThanOrEqual(0);
    expect(skipIdx).toBeLessThan(passedIdx);
  });
});

// ── dispatchReviewResult — other routes still work ────────────────────────────

describe("dispatchReviewResult — change_requested routing", () => {
  it("forwards sshKeyPath to git env so GIT_SSH_COMMAND is set in execSync calls", async () => {
    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const task = makeTask(TASK_ID, { status: "in_review" });
    const wsRoot = makeWorkspaceWithTasks([task]);
    const sshKeyPath = "/home/agent/.ssh/agent_id_rsa";

    const capturedEnvs: (NodeJS.ProcessEnv | undefined)[] = [];
    vi.mocked(execSync).mockImplementation((_cmd, opts) => {
      capturedEnvs.push((opts as { env?: NodeJS.ProcessEnv })?.env);
      return Buffer.from("");
    });
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "change_requested", verdict: "reject", confidence: 0.8, notes: "Fix it" },
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      sshKeyPath,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "review_change_requested")).toBe(true);
    expect(events.some((e) => e.type === "review_mutate_failed")).toBe(false);

    // Every execSync call must carry GIT_SSH_COMMAND pointing at the key.
    expect(capturedEnvs.length).toBeGreaterThan(0);
    for (const env of capturedEnvs) {
      expect(env?.GIT_SSH_COMMAND).toContain(sshKeyPath);
    }
  });

  it("emits review_mutate_failed when task YAML file is missing", async () => {
    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "change_requested", verdict: "reject", confidence: 0.8, notes: "Fix it" },
      workspaceRoot: "/nonexistent",
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "review_mutate_failed")).toBe(true);
    expect(events.some((e) => e.type === "review_change_requested")).toBe(false);
  });
});

describe("dispatchReviewResult — escalate routing", () => {
  it("emits escalation_slack_skipped when SLACK_WEBHOOK_URL is unset", async () => {
    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "escalate", verdict: "escalate", confidence: 0.2, notes: "Too complex" },
      ...baseDispatchOpts,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "escalation_slack_skipped")).toBe(true);
    expect(events.some((e) => e.type === "review_escalate")).toBe(false);
  });

  it("routes escalation through injected NotificationPort when notifier is provided", async () => {
    const task = makeTask(TASK_ID, { status: "in_review" });
    const wsRoot = makeWorkspaceWithTasks([task]);

    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");
    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const notifierCalls: Array<{ trigger: string }> = [];
    const notifier = {
      postTaskMessage: async (_fid: string, _tid: string, trigger: string) => { notifierCalls.push({ trigger }); },
      closeTaskThread: async () => {},
      postFeatureMessage: async () => {},
      closeFeatureThread: async () => {},
    };

    const mockFetch = vi.fn();
    vi.stubGlobal("fetch", mockFetch);

    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "escalate", verdict: "escalate", confidence: 0.2, notes: "Too complex" },
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      notifier,
      emit: (e) => events.push(e),
    });

    // Notifier was used — webhook fetch not called
    expect(notifierCalls).toHaveLength(1);
    expect(notifierCalls[0].trigger).toBe("task_review_changed");
    expect(mockFetch).not.toHaveBeenCalled();
    expect(events.some((e) => e.type === "task_escalated")).toBe(true);
    expect(events.some((e) => e.type === "escalation_slack_skipped")).toBe(false);
  });
});

// ── dispatchReviewResult — change_requested: task PR demote ──────────────────

describe("dispatchReviewResult — change_requested: demotes task PR to draft", () => {
  it("PATCHes PR to draft: true when prUrl and githubToken are provided", async () => {
    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const task = makeTask(TASK_ID, { status: "in_review" });
    const wsRoot = makeWorkspaceWithTasks([task]);

    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockImplementation((cmd) => {
      if (cmd === "curl") {
        return {
          pid: 0, output: [], stdout: JSON.stringify({ html_url: PR_URL, number: 42 }),
          stderr: "", status: 0, signal: null, error: undefined,
        } as unknown as ReturnType<typeof spawnSync>;
      }
      return mockPushSuccess();
    });

    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "change_requested", verdict: "reject", confidence: 0.9, notes: "Fix nulls" },
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      prUrl: PR_URL,
      githubToken: "ghp_test",
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      gitAuthorName: GIT_AUTHOR_NAME,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "review_change_requested")).toBe(true);
    expect(events.some((e) => e.type === "task_pr_demote_failed")).toBe(false);

    const curlCalls = vi.mocked(spMock).mock.calls.filter(([cmd]) => cmd === "curl");
    expect(curlCalls).toHaveLength(1);
    const patchArgs = curlCalls[0][1] as string[];
    expect(patchArgs).toContain("PATCH");
    expect(patchArgs).toContain(JSON.stringify({ draft: true }));

    const updated = readTaskFromDir(wsRoot, TASK_ID);
    expect(updated.status).toBe("change_requested");
  });

  it("emits task_pr_demote_failed when PATCH errors; task still moves to change_requested", async () => {
    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const task = makeTask(TASK_ID, { status: "in_review" });
    const wsRoot = makeWorkspaceWithTasks([task]);

    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockImplementation((cmd) => {
      if (cmd === "curl") {
        return {
          pid: 0, output: [], stdout: "",
          stderr: "curl: (6) Could not resolve host", status: 1, signal: null, error: undefined,
        } as unknown as ReturnType<typeof spawnSync>;
      }
      return mockPushSuccess();
    });

    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "change_requested", verdict: "reject", confidence: 0.9, notes: "Fix nulls" },
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      prUrl: PR_URL,
      githubToken: "ghp_test",
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      gitAuthorName: GIT_AUTHOR_NAME,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "review_change_requested")).toBe(true);
    expect(events.some((e) => e.type === "task_pr_demote_failed")).toBe(true);

    const updated = readTaskFromDir(wsRoot, TASK_ID);
    expect(updated.status).toBe("change_requested");
  });

  it("skips PATCH when prUrl is absent", async () => {
    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const task = makeTask(TASK_ID, { status: "in_review" });
    const wsRoot = makeWorkspaceWithTasks([task]);

    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "change_requested", verdict: "reject", confidence: 0.9, notes: "Fix nulls" },
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      // prUrl intentionally omitted
      githubToken: "ghp_test",
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "review_change_requested")).toBe(true);
    expect(events.some((e) => e.type === "task_pr_demote_failed")).toBe(false);
    const curlCalls = vi.mocked(spMock).mock.calls.filter(([cmd]) => cmd === "curl");
    expect(curlCalls).toHaveLength(0);
  });
});

// ── dispatchReviewResult — self-review skipped (T10) ─────────────────────────

describe("dispatchReviewResult — self_review_skipped: passed result", () => {
  it("emits reviewer_self_review_skipped before review_passed; task stays in_review", async () => {
    const task = makeTask(TASK_ID, { status: "in_review" });
    const wsRoot = makeWorkspaceWithTasks([task]);

    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: {
        terminal_status: "passed",
        verdict: "passed",
        confidence: 0.9,
        notes: "LGTM",
        self_review_skipped: true,
        // review_url absent — review event was skipped due to 422
      },
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      gitAuthorName: GIT_AUTHOR_NAME,
      emit: (e) => events.push(e),
    });

    // reviewer_self_review_skipped must be emitted before review_passed
    const skipIdx = events.findIndex((e) => e.type === "reviewer_self_review_skipped");
    const passedIdx = events.findIndex((e) => e.type === "review_passed");
    expect(skipIdx).toBeGreaterThanOrEqual(0);
    expect(passedIdx).toBeGreaterThanOrEqual(0);
    expect(skipIdx).toBeLessThan(passedIdx);

    // Task stays in_review — the merge poll handles the done transition.
    expect(events.some((e) => e.type === "task_auto_done")).toBe(false);
    const updated = readTaskFromDir(wsRoot, TASK_ID);
    expect(updated.status).toBe("in_review");
  });

  it("reviewer_self_review_skipped carries task_id, feature_id, and pr_number", async () => {
    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const task = makeTask(TASK_ID, { status: "in_review" });
    const wsRoot = makeWorkspaceWithTasks([task]);

    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "passed", verdict: "passed", confidence: 0.9, notes: "", self_review_skipped: true },
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      prUrl: PR_URL, // https://github.com/org/repo/pull/42
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: (e) => events.push(e),
    });

    const skipEvent = events.find((e) => e.type === "reviewer_self_review_skipped");
    expect(skipEvent).toBeDefined();
    expect(skipEvent?.task_id).toBe(TASK_ID);
    expect(skipEvent?.feature_id).toBe(FEATURE_ID);
    expect(skipEvent?.pr_number).toBe(42);
  });
});

describe("dispatchReviewResult — self_review_skipped: change_requested result", () => {
  it("emits reviewer_self_review_skipped and mutates task to change_requested", async () => {
    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const task = makeTask(TASK_ID, { status: "in_review" });
    const wsRoot = makeWorkspaceWithTasks([task]);

    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: {
        terminal_status: "change_requested",
        verdict: "change_requested",
        confidence: 0.85,
        notes: "🔴 Missing null check.",
        self_review_skipped: true,
      },
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      gitAuthorName: GIT_AUTHOR_NAME,
      emit: (e) => events.push(e),
    });

    // reviewer_self_review_skipped emitted before review_change_requested
    const skipIdx = events.findIndex((e) => e.type === "reviewer_self_review_skipped");
    const crIdx = events.findIndex((e) => e.type === "review_change_requested");
    expect(skipIdx).toBeGreaterThanOrEqual(0);
    expect(crIdx).toBeGreaterThanOrEqual(0);
    expect(skipIdx).toBeLessThan(crIdx);

    // task YAML mutated to change_requested
    const updated = readTaskFromDir(wsRoot, TASK_ID);
    expect(updated.status).toBe("change_requested");
  });

  it("does not emit reviewer_self_review_skipped when self_review_skipped is absent", async () => {
    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const task = makeTask(TASK_ID, { status: "in_review" });
    const wsRoot = makeWorkspaceWithTasks([task]);

    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: {
        terminal_status: "passed",
        verdict: "passed",
        confidence: 0.9,
        notes: "LGTM",
        review_url: PR_URL,
