    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const task = makeTask(TASK_ID, {
      status: "in_review",
      log: [
        { action: "review_blocked", by: GIT_AUTHOR_EMAIL, at: "2025-01-01T00:00:00Z", note: "attempt 1" },
        { action: "review_blocked", by: GIT_AUTHOR_EMAIL, at: "2025-01-01T01:00:00Z", note: "attempt 2" },
