/**
 * Container-start bootstrap — validates agent.yaml and emits start/ready events.
 *
 * Git operations (clone/pull of management workspaces and the workflow repo)
 * were removed in T6: pull-workspaces.ts already calls syncRepo on every poll
 * cycle and handles clone-if-missing identically. Bootstrap's only remaining
 * job is to validate the config and fail fast before the polling loop starts.
 *
 * syncRepo and its helpers remain here because pull-workspaces.ts imports them.
 *
 * Exit codes:
 *   0  success
 *   2  agent.yaml validation failed
 *   4  unexpected bootstrap error
 */

import { execSync } from "node:child_process";
import { existsSync, readdirSync, mkdirSync, rmSync } from "node:fs";
import { join } from "node:path";
import { loadAgentYaml, type AgentConfig } from "../config/validate-agent-yaml.js";
import { buildGitEnv } from "../git-env.js";

// ── Exit codes ────────────────────────────────────────────────────────────────

export const EXIT_SUCCESS = 0 as const;
export const EXIT_VALIDATION_FAILED = 2 as const;
export const EXIT_UNEXPECTED = 4 as const;

export type ExitCode = 0 | 2 | 4;

// ── Bootstrap event types ─────────────────────────────────────────────────────

export interface BootstrapStartedEvent {
  type: "bootstrap_started";
  agent_yaml_path: string;
  watches: string[];
  at: string;
}

export interface BootstrapFailedEvent {
  type: "bootstrap_failed";
  reason: string;
  details: string;
  at: string;
}

export interface BootstrapReadyEvent {
  type: "bootstrap_ready";
  at: string;
}

export type BootstrapEvent =
  | BootstrapStartedEvent
  | BootstrapFailedEvent
  | BootstrapReadyEvent;

// ── Public options ────────────────────────────────────────────────────────────

export interface BootstrapOptions {
  /** Absolute path to the agent.yaml file to validate. */
  agentYamlPath: string;
  /**
   * Override the event emitter (default: write JSON to stdout via console.log).
   * Inject a no-op or recording emitter in tests.
   */
  emit?: (event: BootstrapEvent) => void;
}

export interface BootstrapResult {
  exitCode: ExitCode;
  /** Parsed and validated agent config — present only on exit code 0. */
  config?: AgentConfig;
}

// ── Internal helpers ──────────────────────────────────────────────────────────

function defaultEmit(event: BootstrapEvent): void {
  console.log(JSON.stringify(event));
}

export { buildGitEnv };

/** Return true if localPath contains a .git directory. */
function isGitRepo(localPath: string): boolean {
  return existsSync(localPath) && existsSync(join(localPath, ".git"));
}

/**
 * Ensure localPath is an empty directory, ready for git clone.
 *
 * Tries to remove and recreate the directory outright. If that fails because
 * localPath is a Docker volume mount-point root (EBUSY / EPERM on rmdir),
 * falls back to emptying its contents while leaving the root in place.
 * git clone accepts an empty pre-existing directory.
 */
function clearDir(dirPath: string): void {
  if (!existsSync(dirPath)) {
    mkdirSync(dirPath, { recursive: true });
    return;
  }
  try {
    rmSync(dirPath, { recursive: true, force: true });
    mkdirSync(dirPath, { recursive: true });
  } catch {
    // dirPath is a mount-point root — cannot rmdir it; delete contents only.
    for (const entry of readdirSync(dirPath)) {
      rmSync(join(dirPath, entry), { recursive: true, force: true });
    }
  }
}

/**
 * Clone or pull a single git repository.
 * - Already a valid git repo  → fetch + reset --hard to origin/<baseBranch>.
 * - Corrupt .git / missing refs (partial clone)  → wipe and re-clone.
 * - Directory absent, empty, or non-git  → wipe and re-clone.
 * Returns "cloned" | "pulled".
 */
export function syncRepo(
  url: string,
  localPath: string,
  baseBranch: string,
  gitEnv: NodeJS.ProcessEnv,
): "cloned" | "pulled" {
  if (isGitRepo(localPath)) {
    try {
      execSync(`git -C "${localPath}" fetch origin --prune`, { env: gitEnv, stdio: "pipe" });
      // Checkout the base branch before resetting so that reset --hard only
      // moves the base branch pointer. Without this, if a feature branch is
      // currently checked out, reset --hard would corrupt it by moving its
      // HEAD to origin/<baseBranch>, causing downstream pull --rebase calls
      // to replay main's commits onto the feature branch as duplicate commits.
      execSync(`git -C "${localPath}" checkout "${baseBranch}"`, { env: gitEnv, stdio: "pipe" });
      execSync(
        `git -C "${localPath}" reset --hard "origin/${baseBranch}"`,
        { env: gitEnv, stdio: "pipe" },
      );
      return "pulled";
    } catch {
      // Corrupt .git (e.g. partial clone with missing refs) — wipe and re-clone.
    }
  }
  clearDir(localPath);
  execSync(`git clone "${url}" "${localPath}"`, { env: gitEnv, stdio: "pipe" });
  return "cloned";
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Run the container-start bootstrap sequence.
 *
 * @returns A BootstrapResult whose exitCode maps to the process exit code.
 *          The caller is responsible for calling process.exit(result.exitCode).
 */
export async function runBootstrap(opts: BootstrapOptions): Promise<BootstrapResult> {
  const { agentYamlPath, emit = defaultEmit } = opts;

  try {
    // ── 1. Load and validate agent.yaml ──────────────────────────────────────
    let validationResult;
    try {
      validationResult = loadAgentYaml(agentYamlPath);
    } catch (e) {
      emit({
        type: "bootstrap_failed",
        reason: "agent_yaml_unreadable",
        details: `Cannot read ${agentYamlPath}: ${(e as Error).message}`,
        at: new Date().toISOString(),
      });
      return { exitCode: EXIT_VALIDATION_FAILED };
    }

    if (!validationResult.valid) {
      const details = validationResult.errors
        .map((e) => `${e.path}: ${e.message}`)
        .join("; ");
      emit({
        type: "bootstrap_failed",
        reason: "agent_yaml_invalid",
        details,
        at: new Date().toISOString(),
      });
      return { exitCode: EXIT_VALIDATION_FAILED };
    }

    const config = validationResult.config;

    // ── 2. Kill switch ────────────────────────────────────────────────────────
    if (!config.enabled) {
      emit({ type: "bootstrap_ready", at: new Date().toISOString() });
      return { exitCode: EXIT_SUCCESS, config };
    }

    // ── 3. Ready ──────────────────────────────────────────────────────────────
    emit({
      type: "bootstrap_started",
      agent_yaml_path: agentYamlPath,
      watches: config.watches,
      at: new Date().toISOString(),
    });
    emit({ type: "bootstrap_ready", at: new Date().toISOString() });
    return { exitCode: EXIT_SUCCESS, config };
  } catch (e) {
    try {
      emit({
        type: "bootstrap_failed",
        reason: "unexpected_error",
        details: (e as Error).message ?? String(e),
        at: new Date().toISOString(),
      });
    } catch {
      // Last resort — cannot even emit the failure event.
    }
    return { exitCode: EXIT_UNEXPECTED };
  }
}

