// Resolved once at startup so buildAndSubmitExecutor can reuse the same path.
// local-docker ignores this (ClaudeDockerRunAdapter selects the binary differently).
const resolvedExecutorBinPath: string | undefined =
  runtimeProfile !== "local-docker"
    ? resolveExecutorBin(process.env.EXECUTOR_TYPE ?? "claude", {
        hermesModel: process.env.HERMES_INFERENCE_MODEL,
        hermesProvider: process.env.HERMES_INFERENCE_PROVIDER,
        deepseekApiKey: process.env.DEEPSEEK_API_KEY,
        ragMcpUrl: process.env.MCP_RAG_URL,
        hermesMaxTurns: process.env.HERMES_MAX_TURNS ? parseInt(process.env.HERMES_MAX_TURNS, 10) : undefined,
      })
    : undefined;

const ports: RuntimePorts & { broker: { start(): Promise<number>; stop(): Promise<void>; getCallbackUrl(): string | null } } =
  runtimeProfile === "local-docker"
    ? createLocalDockerProfile({
        gitAuthorEmail,
        gitAuthorName,
        sshKeyPath,
        brokerUrl: process.env.BROKER_URL ?? "http://broker:7000",
      })
    : (() => {
        const executorType = process.env.EXECUTOR_TYPE ?? "claude";
        const factoryConfig = {
          hermesModel: process.env.HERMES_INFERENCE_MODEL,
          hermesProvider: process.env.HERMES_INFERENCE_PROVIDER,
          deepseekApiKey: process.env.DEEPSEEK_API_KEY,
          ragMcpUrl: process.env.MCP_RAG_URL,
          hermesMaxTurns: process.env.HERMES_MAX_TURNS ? parseInt(process.env.HERMES_MAX_TURNS, 10) : undefined,
        };
        return createLocalSubprocessProfile({
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
          executor: {
            executorBinPath: resolvedExecutorBinPath,
            extraEnv: resolveExecutorEnv(executorType, factoryConfig),
          },
        });
      })();

// Start the broker receiver (no-op for HttpBrokerAdapter; binds HTTP port for InMemoryBrokerAdapter).
const brokerPort = await ports.broker.start();

const emit = makeEmit(ports);
emit({ type: "broker_started", port: brokerPort, callback_url: ports.broker.getCallbackUrl() });

const bootstrapResult = await runBootstrap({ agentYamlPath });

if (bootstrapResult.exitCode !== 0) return bootstrapResult.exitCode;

const config = bootstrapResult.config!;
const githubToken = process.env.GITHUB_TOKEN ?? "";
if (!githubToken) emit({ type: "warn_no_github_token" });

// ── Notification port — per-workspace factory ─────────────────────────────
// Builds a ThreadedSlackNotifier for a workspace when Slack+Redis config is present;
// falls back to a NullNotifier when config is absent.
const notifierCache = new Map<string, NotificationPort>();
function getNotificationPort(wsRoot: string): NotificationPort {
  if (notifierCache.has(wsRoot)) return notifierCache.get(wsRoot)!;
  const botToken = process.env["SLACK_BOT_TOKEN"];
  const redisUrl = process.env["REDIS_URL"];
  let port: NotificationPort;
  try {
    const notifConfig = loadWorkspaceNotificationConfig(wsRoot);
    const wsYaml = parseYaml(readFileSync(workspaceYamlPath(wsRoot), "utf-8")) as { workspace_id: string };
    const slack = createSlackWebApiClient(botToken, notifConfig?.slack.channelId);
    const store = redisUrl ? buildRedisThreadStore() : null;
    if (slack && store) {
      const service = new ThreadedNotificationService({
        slack, store, workspaceId: wsYaml.workspace_id,
        emit: (e) => emit(e as Record<string, unknown>),
      });
      port = new ThreadedSlackNotifier(service);
    } else {
      port = new NullNotifier();
    }
  } catch {
    port = new NullNotifier();
  }
  notifierCache.set(wsRoot, port);
  return port;
}

// Local counter for local-docker mode — tracks how many executor containers are
// in-flight. Incremented on submit, decremented when the reap loop acks a completion.
// TODO: replace with broker.registrySize() once the broker exposes that endpoint.
let dockerInFlight = 0;
// Tracks in-flight rebase executors by "featureId:taskId" key. Prevents duplicate
// dispatch when the PR poll fires while a rebase executor is still running (docker
// mode has no registrySize() guard equivalent for rebase tasks).
const rebaseInFlight = new Set<string>();
let cycleCount = 0;
const stateInvariantCheckInterval = parseInt(
  process.env.STATE_INVARIANT_CHECK_INTERVAL ?? "5",
  10,
);
const featureReviewInterval = parseInt(
  process.env.FEATURE_REVIEW_INTERVAL ?? "20",
  10,
);

