  }
}

// ── Feature-Tasks-Done checker (every cycle) ──────────────────────────────
async function checkFeatureTasksDoneStep(pulledWorkspaceRoots: string[]): Promise<void> {
  for (const wsRoot of pulledWorkspaceRoots) {
