}

// ── Feature Reviewer Daemon (every FEATURE_REVIEW_INTERVAL cycles) ────────
async function featureReviewStep(pulledWorkspaceRoots: string[]): Promise<void> {
  for (const wsRoot of pulledWorkspaceRoots) {
    try {
      const mgmtCoords = parseManagementRepoCoords(wsRoot);
      await runFeatureReviewCycle({
        workspaceRoot: wsRoot,
        baseBranch: mgmtCoords.baseBranch,
