        anthropicApiKey: process.env.ANTHROPIC_API_KEY,
        slackWebhookUrl: process.env.SLACK_WEBHOOK_URL,
        emit,
      });
    } catch (e) {
      emit({ type: "feature_review_cycle_error", workspace: wsRoot, details: String(e) });
    }
  }
}

// ── State Invariant Checker (every N cycles) ──────────────────────────────
async function stateInvariantStep(pulledWorkspaceRoots: string[]): Promise<void> {
  for (const wsRoot of pulledWorkspaceRoots) {
    try {
      await runStateInvariantCheck({
        workspaceRoot: wsRoot,
        githubToken,
        gitAuthorEmail,
        gitAuthorName,
        sshKeyPath,
        emit,
      });
    } catch (e) {
      emit({ type: "state_invariant_check_error", workspace: wsRoot, details: String(e) });
    }
  }
}

