1	/**
2	 * Shared reap loop — drains completed executions from the broker,
3	 * routes by handle.kind, and dispatches side-effects.
4	 *
5	 * Called once per orchestrator cycle after the claim and review-fix
6	 * concerns have submitted their work. Any orchestrator can drain any
7	 * completion — dispatch is opportunistic, not pinned to the submitter.
8	 *
9	 * Routing:
10	 *   kind=impl       → dispatchExecutorResult (task YAML mutation)
11	 *   kind=review-fix → emit review_dispatch_complete event
12	 *
13	 * Error handling: individual dispatch errors are emitted as events and
14	 * the item is nacked (returned to the queue). Non-throwing.
15	 */
16	
17	import { existsSync } from "node:fs";
18	import { execSync } from "node:child_process";
19	import type { CompletionBrokerPort } from "@workflow/runtime-abi";
20	import { dispatchExecutorResult } from "../side-effects/dispatch.js";
21	import { dispatchReviewResult, type ReviewResult } from "../side-effects/dispatch-review-result.js";
22	import { readTask, writeTask } from "../utils/task-yaml-io.js";
23	import { taskYamlAbsPath, taskYamlRelPath, taskBranchName } from "../paths.js";
24	import { tryReadTaskFromBranch } from "../task-branch-state.js";
25	import type { Task } from "../types/task.js";
26	import {
27	  resolveRepoGitUrl,
28	  resolveRepoBaseBranch,
29	} from "../config/workspace-config.js";
30	import { mutateTaskYaml } from "../side-effects/mutate-task-yaml.js";
31	import { buildGitEnv } from "../git-env.js";
32	import type { NotificationPort } from "../notifications/notification.port.js";
33	
34	// ── Types ─────────────────────────────────────────────────────────────────────
35	
36	export interface ReapLoopOptions {
37	  broker: CompletionBrokerPort;
38	  /** All workspace roots pulled this cycle — used to locate the task YAML. */
39	  workspaceRoots: string[];
40	  /** Visibility-lock duration for peek-and-lock. Default: 30 000 ms. */
41	  lockMs?: number;
42	  /** Max completions to drain per call. Default: 10. */
43	  max?: number;
44	  gitAuthorEmail: string;
45	  gitAuthorName?: string;
46	  sshKeyPath?: string;
47	  githubToken: string;
48	  emit: (event: Record<string, unknown>) => void;
49	  /**
50	   * Shared set of `featureId:taskId` keys for in-flight rebase executors.
51	   * When a rebase completion is acked, its key is removed so the next PR poll
52	   * cycle can dispatch a new rebase if the conflict persists.
53	   */
54	  rebaseInFlight?: Set<string>;
55	  /** Notification port — passed to dispatch functions for task-level notifications. */
56	  notifier?: NotificationPort | null;
57	}
58	
59	export interface ReapLoopResult {
60	  /** Completions successfully dispatched and acked. */
61	  dispatched: number;
62	  /** Completions that failed to dispatch (nacked, will be retried). */
63	  failed: number;
64	}
65	
66	// ── Helpers ───────────────────────────────────────────────────────────────────
67	
68	/**
69	 * Find the workspace root whose tasks directory contains the given task YAML.
70	 * Returns undefined if the task is not found in any pulled workspace.
71	 *
72	 * Checks local FS first (origin/main snapshot). Falls back to the task branch
73	 * on origin for tasks that were added directly to a feature branch without a
74	 * PR to main (e.g. a task whose YAML lives only on feature/<featureId>-<taskId>).
75	 */
76	function findWorkspaceRoot(
77	  workspaceRoots: string[],
78	  featureId: string,
79	  taskId: string,
80	): string | undefined {
81	  const relPath = taskYamlRelPath(featureId, taskId);
82	  const branch = taskBranchName(featureId, taskId);
83	  for (const root of workspaceRoots) {
84	    try {
85	      if (existsSync(taskYamlAbsPath(root, featureId, taskId))) return root;
86	    } catch {
87	      // ignore fs errors
88	    }
89	    // Task not on local FS — check task branch on origin
90	    if (tryReadTaskFromBranch(root, branch, relPath)) return root;
91	  }
92	  return undefined;
93	}
94	
95	/**
96	 * Read a task YAML, falling back to the task branch on origin when the file
97	 * is absent from the local FS (origin/main snapshot).
98	 */
99	function readTaskAny(workspaceRoot: string, featureId: string, taskId: string): Task {
100	  if (existsSync(taskYamlAbsPath(workspaceRoot, featureId, taskId))) {
101	    return readTask(workspaceRoot, featureId, taskId);
102	  }
103	  const relPath = taskYamlRelPath(featureId, taskId);
104	  const branch = taskBranchName(featureId, taskId);
105	  const fromBranch = tryReadTaskFromBranch(workspaceRoot, branch, relPath);
106	  if (fromBranch) return fromBranch;
107	  throw new Error(`task ${featureId}/${taskId} not found on local FS or origin/${branch}`);
108	}
109	
110	// ── Public API ────────────────────────────────────────────────────────────────
111	
112	/**
113	 * Drain the broker completion queue once and dispatch each completion.
114	 * Non-throwing: all errors are emitted and nacked.
115	 */
116	export async function runReapLoop(opts: ReapLoopOptions): Promise<ReapLoopResult> {
117	  const {
118	    broker,
119	    workspaceRoots,
120	    lockMs = 30_000,
121	    max = 10,
122	    gitAuthorEmail,
123	    gitAuthorName,
124	    sshKeyPath,
125	    githubToken,
126	    emit,
127	    rebaseInFlight,
128	    notifier,
129	  } = opts;
130	
131	  const completions = await broker.listCompleted({ max, lockMs });
132	  let dispatched = 0;
133	  let failed = 0;
134	
135	  for (const completion of completions) {
136	    const { handle, result, metadata } = completion;
137	    const { kind, task_id: taskId, feature_id: featureId } = metadata;
138	
139	    try {
140	      const workspaceRoot = findWorkspaceRoot(workspaceRoots, featureId, taskId);
141	      if (!workspaceRoot) {
142	        emit({
143	          type: "reap_workspace_not_found",
144	          handle,
145	          task_id: taskId,
146	          feature_id: featureId,
147	        });
148	        await broker.nack(handle);
149	        failed++;
150	        continue;
151	      }
152	
153	      const taskBranch = `feature/${featureId}-${taskId}`;
154	
155	      if (kind === "impl") {
156	        const task = readTaskAny(workspaceRoot, featureId, taskId);
157	        const taskRepoUrl = resolveRepoGitUrl(workspaceRoot, task.repo);
158	        const taskBaseBranch = resolveRepoBaseBranch(workspaceRoot, task.repo);
159	
160	        await dispatchExecutorResult({
161	          result,
162	          workspaceRoot,
163	          featureId,
164	          taskId,
165	          taskBranch,
166	          taskTitle: task.title,
167	          taskRepoUrl,
168	          taskBaseBranch,
169	          githubToken,
170	          gitAuthorEmail,
171	          gitAuthorName,
172	          sshKeyPath,
173	          notifier,
174	          emit,
175	        });
176	
177	        emit({
178	          type: "executor_result",
179	          task_id: taskId,
180	          feature_id: featureId,
181	          terminal_status: result.terminal_status,
182	        });
183	      } else if (kind === "review-fix") {
184	        emit({
185	          type: "review_dispatch_complete",
186	          task_id: taskId,
187	          feature_id: featureId,
188	          subkind: metadata.subkind ?? "respond",
189	          outcome: result.terminal_status,
190	          handle,
191	        });
192	      } else if (kind === "review") {
193	        const reviewTask = readTaskAny(workspaceRoot, featureId, taskId);
194	        await dispatchReviewResult({
195	          result: result as unknown as ReviewResult,
196	          workspaceRoot,
197	          featureId,
198	          taskId,
199	          taskTitle: reviewTask.title,
200	          prUrl: reviewTask.pr?.url ?? undefined,
201	          gitAuthorEmail,
202	          gitAuthorName,
203	          sshKeyPath,
204	          notifier,
