// ── Public types ──────────────────────────────────────────────────────────────

export type ReviewerDispatchOutcome =
  | "claim_lost"
  | "dispatched";

export interface DispatchReviewerOptions {
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  taskBranch: string;
  implRepoRoot: string;
